query:
query connectivitySnapshotsZtnaAppConnectorSnapshotSummary ( $accountId:ID! $ztnaAppConnectorSnapshotSummaryInput:ZtnaAppConnectorSnapshotSummaryInput!) {
	connectivitySnapshots ( accountId:$accountId ) {
		ztnaAppConnectorSnapshotSummary ( input:$ztnaAppConnectorSnapshotSummaryInput  )  {
			connectivityStatus {
				connectivityStatus
				total
			}
			socketPlatform {
				platform
				total
			}
			socketModel {
				model
				total
			}
			version {
				version
				total
			}
			assignment {
				assigned
				total
			}
			total
		}
	}	
}
